sql:
SELECT COUNT(*) AS transaction_count
FROM fct_transactions
WHERE posting_date >= '2025-01-01' AND posting_date < '2025-04-01';

SELECT AVG(avg_daily_balance) AS avg_daily_deposit_balance
FROM fct_account_balances_monthly
WHERE month_start >= '2026-01-01' AND month_start < '2026-04-01';

SELECT SUM(month_end_balance) AS total_deposit_balance
FROM fct_account_balances_monthly
WHERE month_start = '2026-03-01';

SELECT SUM(amount) AS total_transaction_volume
FROM fct_transactions
WHERE EXTRACT(YEAR FROM transaction_date) = 2024;

SELECT COUNT(*) AS transaction_count
FROM fct_transactions
WHERE EXTRACT(YEAR FROM transaction_date) = 2024;

SELECT COUNT(*) AS transaction_count
FROM fct_transactions
WHERE EXTRACT(YEAR FROM transaction_date) = 2025;
